import { toString } from 'langium/generate';

import { Artifact } from '../artifact-generator.js';
import { JavaClientAPIGeneratorConfig, toPath } from '../java-gen-utils.js';
import { toNodeTree } from '../util.js';

export function generateStreamConsumer(artifactConfig: JavaClientAPIGeneratorConfig): Artifact {
	const packageName = artifactConfig.rootPackageName;

	const node = toNodeTree(`
// Generated by RSD - Do not modify
package ${packageName};

import java.util.function.Consumer;

public interface StreamConsumer<T, E extends RSDError> {
	public void accept(T value, E error, boolean isComplete);

	public static <T, E extends RSDError> StreamConsumer<T, E> of(
			Consumer<T> valueConsumer,
			Consumer<E> errorConsumer,
			Runnable completeConsumer) {
		return new StreamConsumer<T, E>() {
			@Override
			public void accept(T value, E error, boolean isComplete) {
				if (error != null) {
					errorConsumer.accept(error);
				} else if (isComplete) {
					completeConsumer.run();
				} else {
					valueConsumer.accept(value);
				}
			}
		};
	}
}
`);

	return {
		name: 'StreamConsumer.java',
		content: toString(node, '\t'),
		path: toPath(artifactConfig.targetFolder, packageName),
	};
}
